export class Contador {
  cantidad = 0;                    // propiedad común: NO avisa
  readonly total = signal(0);      // signal: avisa

  constructor() {
    setInterval(() => {
      this.cantidad++;             // la pantalla NO se actualiza (no hay zone.js que lo note)
      this.total.update(t => t + 1); // la pantalla SÍ se actualiza
    }, 1000);
  }
}

